 type BrowserFactory<T> = () => T;

 export type BrowserInstanceCreator<T> = BrowserConstructor<T> | BrowserFactory<T>;

 const isMockFactory = <T>(
   Creator: BrowserInstanceCreator<T>,
 ): Creator is BrowserFactory<T> =>
   Boolean((Creator as { _isMockFunction?: unknown })._isMockFunction);

 export const createBrowserInstance = <T>(
   Creator: BrowserInstanceCreator<T>,
 ): T => {
   if (isMockFactory(Creator)) {
     return Creator();
   }

   try {
     return new (Creator as BrowserConstructor<T>)();
   } catch (error) {
     if (
       error instanceof TypeError &&
       error.message.includes(NON_CONSTRUCTABLE_MESSAGE)
     ) {
       return (Creator as BrowserFactory<T>)();
     }

     throw error;
   }
 };

